// 이 함수는 그대로 두세요
async function save(url) {
  const res = await fetch(url);
  if (!res.ok) {
    throw new Error('저장하지 못했습니다 (' + res.status + ')');
  }
  return true;
}

async function saveAll(urls) {
  let saved = 0;
  const failed = [];

  for (const url of urls) {
    try {
      await save(url);
      saved += 1;
    } catch (e) {
      failed.push(url);
    }
  }

  return { saved, failed };
}
